window.kazapP13_getLockedAllowedSections = function () {
  return ["accueil", "abonnement", "parametres"];
};

window.kazapP13_isFullLockActive = function (v) {
  v = v || window.KAZAP?.vendorData;
  const vn = typeof kazapP8_normalizePlan === "function" ? kazapP8_normalizePlan(v) : v;
  const isPaidPlan = !!(vn && ["basique", "pro", "premium"].includes(vn.plan));
  if (isPaidPlan) return false;
  const trialActive = typeof kazapP12_isTrialActive === "function" ? kazapP12_isTrialActive(v) : true;
  return trialActive === false;
};

window._kazapP13OriginalHTML = window._kazapP13OriginalHTML || {};

window.kazapP13_renderFullLockPanel = function (name) {
  document.querySelectorAll(".dash-section").forEach(function (s) {
    s.style.display = "none";
  });
  const target = document.getElementById("ds-" + name);
  if (!target) return;
  if (!(name in window._kazapP13OriginalHTML)) {
    window._kazapP13OriginalHTML[name] = target.innerHTML;
  }
  const _t = function (key, fallback) {
    return typeof t === "function" ? t(key) : fallback;
  };
  target.style.display = "block";
  target.innerHTML =
    '<div class="p10-upgrade-panel">' +
    '<div class="p10-title">' + _t("p13.lockedTitle", "Fonctionnalité réservée aux abonnés") + "</div>" +
    '<div class="p10-desc">' + _t("p13.lockedDesc", "Souscrivez à un plan pour débloquer cette fonctionnalité.") + "</div>" +
    '<button class="btn btn-orange" onclick="kazapP10_goToAbonnement()">' + _t("trial.expiredCta", "Voir les offres →") + "</button>" +
    "</div>";
};

window.kazapP13_restoreSectionIfSaved = function (name) {
  const target = document.getElementById("ds-" + name);
  if (target && window._kazapP13OriginalHTML && name in window._kazapP13OriginalHTML) {
    target.innerHTML = window._kazapP13OriginalHTML[name];
    delete window._kazapP13OriginalHTML[name];
    if (typeof renderTranslations === "function") renderTranslations();
  }
};

(function kazapP13_patchShowDashSection() {
  function _apply() {
    const _origShowDashSection = window.showDashSection;
    if (typeof _origShowDashSection !== "function") return false;
    window.showDashSection = function (name) {
      if (typeof kazapP13_isFullLockActive === "function" && kazapP13_isFullLockActive()) {
        const _allowed = typeof kazapP13_getLockedAllowedSections === "function"
          ? kazapP13_getLockedAllowedSections()
          : ["accueil", "abonnement", "parametres"];
        if (_allowed.indexOf(name) === -1) {
          try {
            localStorage.setItem(window.kazapScopedKey("kazapLastSection"), name);
          } catch (e) {}
          kazapP13_renderFullLockPanel(name);
          document.querySelectorAll(".snav-item").forEach(function (i) {
            i.classList.remove("active");
          });
          const _navItem = document.querySelector('.snav-item[data-section="' + name + '"]');
          if (_navItem) _navItem.classList.add("active");
          const _topbarTitle = document.getElementById("topbar-title");
          if (_topbarTitle) {
            _topbarTitle.textContent = (typeof SECTION_TITLES !== "undefined" && SECTION_TITLES[name]) || name;
          }
          const _sidebarEl = document.getElementById("dash-sidebar");
          if (_sidebarEl) _sidebarEl.classList.remove("mob-open");
          const _sidebarOverlay = document.getElementById("sidebar-overlay");
          if (_sidebarOverlay) _sidebarOverlay.classList.remove("active");
          document.querySelectorAll(".mob-nav-item").forEach(function (i) {
            i.classList.remove("active");
          });
          const _mobItem = document.querySelector('.mob-nav-item[data-section="' + name + '"]');
          if (_mobItem) _mobItem.classList.add("active");
          return;
        }
      }
      if (typeof kazapP13_restoreSectionIfSaved === "function") kazapP13_restoreSectionIfSaved(name);
      return _origShowDashSection(name);
    };
    return true;
  }
  if (!_apply()) document.addEventListener("DOMContentLoaded", kazapP13_patchShowDashSection);
  logger.log("[KAZAP Partie 13] showDashSection patché avec succès (verrouillage complet post-essai).");
})();

(function kazapP13_patchShowDashboard() {
  function _apply() {
    const _origShowDashboard = window.showDashboard;
    if (typeof _origShowDashboard !== "function") return false;
    window.showDashboard = function () {
      if (typeof kazapP13_isFullLockActive === "function" && kazapP13_isFullLockActive()) {
        try {
          const _allowed = typeof kazapP13_getLockedAllowedSections === "function"
            ? kazapP13_getLockedAllowedSections()
            : ["accueil", "abonnement", "parametres"];
          const _savedSection = localStorage.getItem(window.kazapScopedKey("kazapLastSection"));
          if (_savedSection && _allowed.indexOf(_savedSection) === -1) {
            localStorage.setItem(window.kazapScopedKey("kazapLastSection"), "accueil");
          }
        } catch (e) {}
      }
      return _origShowDashboard();
    };
    return true;
  }
  if (!_apply()) document.addEventListener("DOMContentLoaded", kazapP13_patchShowDashboard);
  logger.log("[KAZAP Partie 13] showDashboard patché avec succès (redirection Accueil au premier chargement si verrouillé).");
})();

