/* ==========================================================================
   [KAZAP Partie 13 - Partie 2/2] Cadenas de navigation et message generique
   Ajout additif — ne modifie aucune ligne existante de kazapP10_applyNavLockState.
   ========================================================================== */

window.kazapP13_applyFullNavLockState = function () {
  if (typeof kazapP13_isFullLockActive !== "function" || typeof kazapP13_getLockedAllowedSections !== "function") return;
  const _fullLocked = kazapP13_isFullLockActive();
  const _allowed = kazapP13_getLockedAllowedSections();
  document.querySelectorAll(".snav-item, .mob-nav-item").forEach(function (el) {
    const sectionName = el.getAttribute("data-section");
    if (!sectionName) return;
    if (sectionName === "agenda" || sectionName === "ia") return;
    const locked = _fullLocked && _allowed.indexOf(sectionName) === -1;
    el.classList.toggle("p10-locked", locked);
    if (el.classList.contains("snav-item")) {
      let lockBadge = el.querySelector(".p10-lock-badge");
      if (locked && !lockBadge) {
        lockBadge = document.createElement("span");
        lockBadge.className = "p10-lock-badge";
        lockBadge.textContent = "";
        el.appendChild(lockBadge);
      } else if (!locked && lockBadge) {
        lockBadge.remove();
      }
    }
  });
};

(function kazapP13_patchRenderPlanBadgeForNavLock() {
  function _apply() {
    const _orig = window.kazapP9_renderPlanBadge;
    if (typeof _orig !== "function") return false;
    window.kazapP9_renderPlanBadge = function (v) {
      _orig(v);
      if (typeof kazapP13_applyFullNavLockState === "function") kazapP13_applyFullNavLockState();
    };
    return true;
  }
  if (!_apply()) document.addEventListener("DOMContentLoaded", kazapP13_patchRenderPlanBadgeForNavLock);
  logger.log("[KAZAP Partie 13] kazapP9_renderPlanBadge patché avec succès (cadenas nav verrouillage complet).");
})();

(function kazapP13_patchOnPlanActivatedForNavLock() {
  function _apply() {
    const _orig = window.kazapP7_onPlanActivated;
    if (typeof _orig !== "function") return false;
    window.kazapP7_onPlanActivated = function (newPlan, extraFields) {
      _orig(newPlan, extraFields);
      if (typeof kazapP13_applyFullNavLockState === "function") kazapP13_applyFullNavLockState();
    };
    return true;
  }
  if (!_apply()) document.addEventListener("DOMContentLoaded", kazapP13_patchOnPlanActivatedForNavLock);
  logger.log("[KAZAP Partie 13] kazapP7_onPlanActivated patché avec succès (cadenas nav verrouillage complet).");
})();

